/**
 * Kumva WaitForResponse Node
 * Waits for user input (SMS reply, DTMF, etc.) with configurable timeout
 */

module.exports = function(RED) {
  const SessionManager = require('kumva-insights/utils/session-manager');
  const DataStorage = require('kumva-insights/utils/data-storage');
  const ConfigManager = require('kumva-insights/utils/config-manager');
  const helpers = require('kumva-insights/utils/helpers');

  // Global managers (shared with other nodes)
  let globalSessionManager = null;
  let globalDataStorage = null;
  let globalConfigManager = null;

  /**
   * Initialize global dependencies
   */
  async function initializeGlobals() {
    if (!globalSessionManager) {
      globalConfigManager = new ConfigManager();
      
      globalSessionManager = new SessionManager(globalConfigManager.getRedisConfig());
      await globalSessionManager.initialize();

      globalDataStorage = new DataStorage(globalConfigManager.getStoragePath());
    }

    return {
      sessionManager: globalSessionManager,
      dataStorage: globalDataStorage,
      configManager: globalConfigManager
    };
  }

  function KumvaWaitForResponseNode(config) {
    RED.nodes.createNode(this, config);
    const node = this;

    // Active waiting sessions
    const waitingSessions = new Map();

    // Initialize globals
    initializeGlobals().catch(error => {
      node.error(`Failed to initialize: ${error.message}`);
    });

    /**
     * Handle response from webhook
     */
    async function handleWebhookResponse(responseData, msg) {
      const { sessionManager } = await initializeGlobals();
      const flowId = RED.settings.context?.global?.flowId || node.z;
      const webhookManager = RED.nodes.getWebhookManager?.(flowId);

      if (webhookManager) {
        webhookManager.unregisterWaitingNode(msg.sessionId);
      }

      // Format response
      const formattedResponse = helpers.formatResponseData({
        content: responseData.content,
        type: responseData.type,
        dtmfInput: responseData.dtmfInput
      });

      // Store if enabled
      if (config.storeResponses) {
        await sessionManager.storeResponse(msg.sessionId, formattedResponse);
      }

      // Validate if needed
      if (config.validateResponse) {
        const rules = config.validationRules ? JSON.parse(config.validationRules) : null;
        const validation = validateResponse(formattedResponse.content, rules);
        
        if (!validation.valid && config.onValidationFail === 'reject') {
          node.send([null, { ...msg, retryCount: (msg.retryCount || 0) + 1, validationErrors: validation.errors }]);
          return;
        }
      }

      // Send to output
      node.send({
        ...msg,
        response: formattedResponse.content,
        responseType: responseData.type,
        rawResponse: responseData,
        waitStatus: 'response-received'
      });
    }

    /**
     * Setup response listener for a session
     */
    async function setupResponseListener(sessionId, msg, timeoutMs) {
      const { sessionManager, dataStorage } = await initializeGlobals();

      return new Promise((resolve, reject) => {
        // Create timeout
        const timeout = setTimeout(async () => {
          waitingSessions.delete(sessionId);

          if (config.handleTimeout === 'retry') {
            // Send retry prompt
            msg.retryCount = (msg.retryCount || 0) + 1;
            msg.waitStatus = 'timeout-retry';
            
            node.status({
              fill: 'orange',
              shape: 'dot',
              text: `Timeout (retry ${msg.retryCount})`
            });

            resolve({
              status: 'timeout',
              action: 'retry',
              retryCount: msg.retryCount,
              maxRetries: config.maxRetries || 3
            });
          } else if (config.handleTimeout === 'fallback') {
            // Route to fallback output
            msg.waitStatus = 'timeout-fallback';
            
            node.status({
              fill: 'orange',
              shape: 'dot',
              text: 'Timeout'
            });

            resolve({
              status: 'timeout',
              action: 'fallback'
            });
          } else {
            // Default: continue with null response
            msg.waitStatus = 'timeout-continue';
            
            node.status({
              fill: 'orange',
              shape: 'dot',
              text: 'Timeout'
            });

            resolve({
              status: 'timeout',
              action: 'continue'
            });
          }
        }, timeoutMs);

        // Store session info for webhook handler
        waitingSessions.set(sessionId, {
          nodeId: node.id,
          timeout: timeout,
          resolve: resolve,
          reject: reject,
          msg: msg
        });

        node.status({
          fill: 'blue',
          shape: 'ring',
          text: `Waiting (${timeoutMs / 1000}s)`
        });
      });
    }

    /**
     * Process received response
     */
    async function processResponse(sessionId, responseData) {
      const { sessionManager, dataStorage } = await initializeGlobals();

      const waitSession = waitingSessions.get(sessionId);
      if (!waitSession) {
        return; // No one waiting for this response
      }

      // Clear timeout
      clearTimeout(waitSession.timeout);
      waitingSessions.delete(sessionId);

      // Get current session data
      const sessionResult = await sessionManager.getSession(sessionId);
      if (!sessionResult.exists) {
        waitSession.reject(new Error('Session not found'));
        return;
      }

      const session = sessionResult.data;
      const msg = waitSession.msg;

      // Format response data
      const formattedResponse = helpers.formatResponseData(responseData);

      // Store response if enabled
      if (session.storeResponses || config.storeResponses) {
        const storeResult = await sessionManager.storeResponse(sessionId, formattedResponse);
        if (!storeResult.success) {
          node.warn(`Failed to store response: ${storeResult.error}`);
        }
      }

      // Update session with response
      await sessionManager.updateSession(sessionId, {
        lastResponse: formattedResponse,
        lastUpdated: new Date().toISOString(),
        responseCount: (session.responseCount || 0) + 1
      });

      // Prepare output message
      const outputMsg = {
        ...msg,
        response: formattedResponse.content,
        responseType: formattedResponse.type,
        dtmfInput: formattedResponse.dtmfInput || null,
        rawResponse: responseData,
        waitStatus: 'response-received',
        _kumva: {
          ...msg._kumva,
          lastResponse: formattedResponse,
          responseTimestamp: new Date().toISOString()
        }
      };

      // Apply response validation if configured
      if (config.validateResponse) {
        const validation = validateResponse(formattedResponse.content, config.validationRules);
        outputMsg.validationResult = validation;
        
        if (!validation.valid && config.onValidationFail === 'reject') {
          node.warn(`Response validation failed: ${validation.errors.join(', ')}`);
          waitSession.resolve({
            status: 'validation-failed',
            action: 'retry',
            errors: validation.errors
          });
          return;
        }
      }

      node.status({
        fill: 'green',
        shape: 'dot',
        text: 'Response received'
      });

      waitSession.resolve({
        status: 'response-received',
        action: 'continue',
        message: outputMsg
      });
    }

    /**
     * Validate response based on rules
     */
    function validateResponse(response, rules) {
      const errors = [];

      if (!rules) {
        return { valid: true, errors };
      }

      // Check minimum length
      if (rules.minLength && response.length < rules.minLength) {
        errors.push(`Response too short (min: ${rules.minLength})`);
      }

      // Check maximum length
      if (rules.maxLength && response.length > rules.maxLength) {
        errors.push(`Response too long (max: ${rules.maxLength})`);
      }

      // Check pattern (regex)
      if (rules.pattern) {
        const regex = new RegExp(rules.pattern);
        if (!regex.test(response)) {
          errors.push(`Response doesn't match pattern: ${rules.pattern}`);
        }
      }

      // Check allowed values
      if (rules.allowedValues && Array.isArray(rules.allowedValues)) {
        if (!rules.allowedValues.includes(response)) {
          errors.push(`Response must be one of: ${rules.allowedValues.join(', ')}`);
        }
      }

      // Check numeric range
      if (rules.minValue !== undefined || rules.maxValue !== undefined) {
        const numValue = parseInt(response);
        if (isNaN(numValue)) {
          errors.push('Response must be numeric');
        } else {
          if (rules.minValue !== undefined && numValue < rules.minValue) {
            errors.push(`Response must be >= ${rules.minValue}`);
          }
          if (rules.maxValue !== undefined && numValue > rules.maxValue) {
            errors.push(`Response must be <= ${rules.maxValue}`);
          }
        }
      }

      return {
        valid: errors.length === 0,
        errors
      };
    }

    /**
     * Handle incoming messages (start waiting for response)
     */
    node.on('input', async function(msg) {
      try {
        const { sessionManager } = await initializeGlobals();

        // Validate required fields
        if (!msg.sessionId) {
          node.error('Missing sessionId in message');
          node.status({
            fill: 'red',
            shape: 'ring',
            text: 'No sessionId'
          });
          return;
        }

        // Get session to verify it exists
        const sessionResult = await sessionManager.getSession(msg.sessionId);
        if (!sessionResult.exists) {
          node.error(`Session not found: ${msg.sessionId}`);
          node.status({
            fill: 'red',
            shape: 'ring',
            text: 'Session not found'
          });
          return;
        }

        // Register with webhook manager
        const flowId = RED.settings.context?.global?.flowId || node.z;
        const webhookManager = RED.nodes.getWebhookManager?.(flowId);
        
        if (webhookManager) {
          webhookManager.registerWaitingNode(msg.sessionId, {
            nodeId: node.id,
            flowId: flowId,
            callback: (responseData) => {
              // Handle response from webhook
              handleWebhookResponse(responseData, msg);
            }
          });
        }

        // Parse timeout
        const timeoutMs = helpers.getTimeoutMs(
          config.responseTimeout || '30s'
        );

        // Setup listener and wait for response
        const result = await setupResponseListener(msg.sessionId, msg, timeoutMs);

        // Handle result based on action
        switch(result.action) {
          case 'retry':
            // Send retry message to output 1 (retry)
            node.send([null, {
              ...msg,
              retryCount: result.retryCount,
              maxRetries: result.maxRetries,
              waitStatus: 'timeout-retry'
            }]);
            break;

          case 'fallback':
            // Send fallback message to output 2 (fallback)
            node.send([null, null, {
              ...msg,
              waitStatus: 'timeout-fallback'
            }]);
            break;

          case 'continue':
            // Continue with original message (null response)
            msg.waitStatus = 'timeout-continue';
            msg.response = null;
            node.send(msg);
            break;

          case 'validation-failed':
            // Send to retry output
            node.send([null, {
              ...msg,
              retryCount: (msg.retryCount || 0) + 1,
              maxRetries: config.maxRetries || 3,
              validationErrors: result.errors,
              waitStatus: 'validation-failed'
            }]);
            break;

          default:
            // Response received
            if (result.message) {
              node.send(result.message);
            }
        }

      } catch (error) {
        node.error(`WaitForResponse error: ${error.message}`);
        node.status({
          fill: 'red',
          shape: 'ring',
          text: 'Error'
        });

        msg.waitStatus = 'error';
        msg.waitError = error.message;
        node.send(msg);
      }
    });

    /**
     * Handle webhook callback
     */
    node.on('webhook-response', async function(sessionId, responseData) {
      try {
        await processResponse(sessionId, responseData);
      } catch (error) {
        node.error(`Webhook processing error: ${error.message}`);
      }
    });

    /**
     * Cleanup on close
     */
    node.on('close', function(done) {
      // Clear all active waiting sessions
      waitingSessions.forEach((session) => {
        clearTimeout(session.timeout);
      });
      waitingSessions.clear();
      done();
    });

    // Initialize status
    node.status({
      fill: 'yellow',
      shape: 'ring',
      text: 'Ready'
    });
  }

  RED.nodes.registerType('kumva-wait-for-response', KumvaWaitForResponseNode);
};